import assert from 'node:assert/strict';

export async function runMotionNameSmoke(page){
 const previous=await page.evaluate(()=>({project:JSON.stringify(project),curPage,curSec,curEl,curPane,selection,secFocus,mode:NAGWEB_STORY_EDITOR.canvasMode(),timeline:NAGWEB_STORY_TIMELINE_UI.state()}));
 try{
  await page.evaluate(()=>{project.pages[0].sections=[mkSection({layout:'free',sdEnabled:false,elements:[mkEl('label',{name:'Exterior',text:'Fuera del grupo'})]})];curPage=0;curSec=0;curEl=0;selection=[];secFocus=false;saveProject();renderPane();renderPreview();history=[];future=[];});
  const before=await page.evaluate(()=>({project:JSON.stringify(project),stored:localStorage.getItem(STORE_KEY),outside:sec().elements[0],assets:project.assets.images.length}));
  async function ready(id){await page.waitForFunction(id=>{const d=document.querySelector('.nw-motion-dialog iframe')?.contentDocument;return id?d?.querySelector('[data-id="'+id+'"].nw-motion-selected'):d?.querySelector('[data-motion-canvas]');},{},id);}
  async function layers(){return page.$$eval('[data-motion-layer]',ns=>ns.map(n=>({id:n.dataset.motionLayer,name:n.querySelector('strong').textContent})));}
  async function choose(id){await page.click('[data-motion-layer="'+id+'"]');await ready(id);}
  async function rename(value,key='Enter'){await page.click('[data-motion-element-name]');await page.keyboard.down('Control');await page.keyboard.press('A');await page.keyboard.up('Control');await page.keyboard.type(value);await page.keyboard.press(key);}
  async function pose(id,selector='.nw-motion-dialog iframe',gid){return page.evaluate(({id,selector,gid})=>{const f=document.querySelector(selector),d=f.contentDocument;f.contentWindow.__NAG_SCROLL_DIRECTOR[gid||d.querySelector('.sc').dataset.id].set(.2);const n=d.querySelector('[data-id="'+id+'"]');return {vars:['x','y','z','rx','ry','scale','rot','opacity','blur'].map(k=>n.style.getPropertyValue('--nw-sd-'+k)),base:[n.style.left,n.style.top,n.style.width,n.style.getPropertyValue('--rot')],src:n.querySelector('img')?.getAttribute('src')};},{id,selector,gid});}
  await page.click('.tb-left [data-motion-open]');await ready();assert.equal(await page.$eval('[data-motion-element-name]',n=>n.disabled),true);await page.click('[data-motion-library-tab="elements"]');const original=await layers(),image=original[0],heading=original[4];await choose(image.id);assert.equal(await page.$eval('[data-motion-element-name]',n=>n.value),image.name);const prepared=await pose(image.id);await page.$eval('.nw-motion-dialog iframe',f=>f.contentDocument.body.dataset.nameProbe='same');
  const imageName='<b>Portada</b> "A"';await rename('  '+imageName+'  ');assert.equal(await page.$eval('[data-motion-element-name]',n=>n.value),imageName);assert.equal((await layers())[0].name,imageName);assert.equal(await page.$eval('[data-motion-selection]',n=>n.textContent),imageName);assert.equal(await page.$eval('[data-motion-content="0"]',n=>n.closest('.crow').querySelector('label').textContent),imageName);assert.equal(await page.$eval('[data-motion-upload="0"]',n=>n.getAttribute('aria-label')),'Cargar imagen para '+imageName);assert.equal(await page.$('[data-motion-layer] b'),null,'Names remain literal text');assert.equal(await page.$eval('.nw-motion-dialog iframe',(f,id)=>f.contentDocument.querySelector('[data-id="'+id+'"]').getAttribute('aria-label'),image.id),'Seleccionar '+imageName);assert.equal(await page.$eval('.nw-motion-dialog iframe',f=>f.contentDocument.body.dataset.nameProbe),'same','Renaming does not regenerate the iframe');assert.deepEqual(await pose(image.id),prepared);
  await rename('Sin confirmar','Escape');assert.equal(await page.$eval('[data-motion-element-name]',n=>n.value),imageName);assert.equal((await layers())[0].name,imageName);assert.equal(await page.$eval('.nw-motion-dialog',n=>n.open),true,'Escape cancels the field instead of closing the dialog');await rename('   ');assert.equal(await page.$eval('[data-motion-element-name]',n=>n.value),imageName,'Blank names keep the previous name');
  await choose(heading.id);const headingText=await page.$eval('[data-motion-content="4"]',n=>n.value);await rename('Título principal','Tab');assert.equal((await layers())[4].name,'Título principal');assert.equal(await page.$eval('[data-motion-content="4"]',n=>n.value),headingText,'Naming does not change visible content');
  await page.click('[data-motion-library-tab="library"]');await page.click('[data-motion-template="soft-orbit"]');await page.waitForFunction(()=>document.querySelector('.nw-motion-dialog iframe')?.contentDocument?.querySelector('.hd')?.textContent==='Diseño en movimiento.');assert.equal((await layers()).some(n=>n.name===imageName),false);await page.click('[data-motion-template="iso-focus"]');await ready(heading.id);assert.equal((await layers())[0].name,imageName);assert.equal((await layers())[4].name,'Título principal');assert.equal(await page.$eval('[data-motion-element-name]',n=>n.value),'Título principal');assert.equal(await page.$eval('.nw-motion-dialog iframe',(f,id)=>f.contentDocument.querySelector('[data-id="'+id+'"]').getAttribute('aria-label'),image.id),'Seleccionar '+imageName);assert.equal(await page.evaluate(()=>JSON.stringify(project)),before.project);assert.equal(await page.evaluate(()=>localStorage.getItem(STORE_KEY)),before.stored);assert.equal(await page.evaluate(()=>history.length),0);
  await page.click('[data-motion-insert-group]');const inserted=await page.evaluate(()=>{const g=sec().elements.find(e=>e.nwMotionInstance);return {project:JSON.stringify(project),gid:g.id,members:sec().elements.filter(e=>e.parent===g.id),outside:sec().elements[0],assets:project.assets.images.length};});assert.equal(inserted.members.find(e=>e.id===image.id).name,imageName);assert.equal(inserted.members.find(e=>e.id===heading.id).name,'Título principal');assert.equal(inserted.members.find(e=>e.id===heading.id).text,headingText);assert.equal(inserted.assets,before.assets+3);assert.deepEqual(inserted.outside,before.outside);
  await page.evaluate(gid=>NAGWEB_MOTION_LAB.edit(gid),inserted.gid);await ready();await page.click('[data-motion-library-tab="elements"]');await choose(image.id);assert.equal(await page.$eval('[data-motion-element-name]',n=>n.value),imageName);await rename('Imagen de apertura');await page.click('[data-motion-save]');const saved=await page.evaluate(gid=>({project:JSON.stringify(project),members:sec().elements.filter(e=>e.parent===gid),outside:sec().elements[0],groups:sec().elements.filter(e=>e.nwMotionInstance).length,assets:project.assets.images.length}),inserted.gid);assert.equal(saved.groups,1);assert.equal(saved.assets,inserted.assets);assert.deepEqual(saved.outside,before.outside);assert.deepEqual(saved.members,inserted.members.map(e=>e.id===image.id?{...e,name:'Imagen de apertura'}:e),'Only the chosen element name changes');
  await page.evaluate(gid=>NAGWEB_MOTION_LAB.edit(gid),inserted.gid);await ready();await page.click('[data-motion-library-tab="elements"]');await choose(image.id);await rename('Nombre descartado');await page.click('[data-motion-close]');assert.equal(await page.evaluate(()=>JSON.stringify(project)),saved.project);await page.evaluate(()=>undo());assert.equal(await page.evaluate(()=>JSON.stringify(project)),inserted.project);await page.evaluate(()=>redo());assert.equal(await page.evaluate(()=>JSON.stringify(project)),saved.project);
  await page.evaluate(()=>{const f=document.createElement('iframe');f.id='name-export';f.srcdoc=generateSite(flattenPage(page()),false,false,false);document.body.append(f);});await page.waitForFunction(gid=>document.querySelector('#name-export')?.contentWindow?.__NAG_SCROLL_DIRECTOR?.[gid],{},inserted.gid);const exported=await pose(image.id,'#name-export',inserted.gid);assert.deepEqual(exported.vars,prepared.vars);assert.equal(exported.src,prepared.src);assert.equal(await page.$eval('#name-export',(f,id)=>f.contentDocument.querySelector('[data-id="'+id+'"]').textContent,heading.id),headingText);
  console.log('Nombres Motion Lab: teclado Enter/Tab/Escape, vacíos sin pérdida, texto literal, lista/inspector/accesibilidad sincronizados sin recargar, contenido y movimiento intactos, borradores, misma instancia, cancelar, historial y exportación OK');
 }finally{
  await page.evaluate(p=>{document.querySelector('.nw-motion-dialog').close();document.querySelector('#name-export')?.remove();clearTimeout(previewTimer);project=JSON.parse(p.project);curPage=p.curPage;curSec=p.curSec;curEl=p.curEl;curPane=p.curPane;selection=p.selection;secFocus=p.secFocus;history=[];future=[];NAGWEB_STORY_EDITOR.setCanvasMode(p.mode);NAGWEB_STORY_TIMELINE_UI.setState(p.timeline);saveProject();renderScenes();renderPane();renderPreview();},previous);
 }
}
